fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, w / 2 * 16);
        host::display::state_set(2, 0);
    }
    let target: i32 = host::display::pointer_x() * 16;
    let mut x: i32 = host::display::state_get(1);
    let mut v: i32 = host::display::state_get(2);
    v = v + (target - x) / 16;
    v = v * 7 / 8;
    x = x + v;
    host::display::state_set(1, x);
    host::display::state_set(2, v);
    host::display::clear(0x000000);
    host::display::fill_rect(target / 16, 0, 1, h, 0x304050);
    host::display::fill_rect(x / 16 - 14, h / 2 - 14, 28, 28, 0x40ffa0);
    host::display::present();
}
